function getSubtree(nodeMap: NodeMap, range: TETextRange): Subtree {
  const start = range.start;
  const end = range.end;

  const subtree = new Subtree();

  const stack = [start];
  while (stack.length > 0) {
    const node = stack.pop();
    if (node.id === end.id) {
      subtree.end = node;
      break;
    }

    if (node.children) {
      for (let i = node.children.length - 1; i >= 0; i--) {
        stack.push(node.children[i]);
      }
    }
  }

  return subtree;
}
```

