        const resolvedAction = isFunction(action) ? action(state) : action;
        if (tr && resolvedAction) {
          dispatch(tr.setMeta(pluginKey, resolvedAction));
        } else {
          return false;
        }
      }
      return true;
    },

    getPluginState: (state) => pluginKey.getState(state),
  };
}

