function generate(n: number): number[][] {
  const triangle: number[][] = [];

  for (let i = 0; i < n; i++) {
    const row: number[] = [];

    for (let j = 0; j <= i; j++) {
      if (j === 0 || j === i) {
        row.push(1);
      } else {
        row.push(triangle[i - 1][j - 1] + triangle[i - 1][j]);
      }
    }

    triangle.push(row);
  }

  return triangle;
}
```

