function createRampCurve3(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  isVertical: boolean
): (x: number) => number {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const slope = dy / dx;
  const intercept = y1 - slope * x1;

  return (x: number) => {
    if (isVertical) {
      return x;
    } else {
      return slope * x + intercept;
    }
  };
}
