function radialVertices(
  origin: Point,
  radius: number,
  vertices: number,
  rotation: number
): Point[] {
  const angle = (2 * Math.PI) / vertices;
  const points: Point[] = [];
  for (let i = 0; i < vertices; i++) {
    const x = origin.x + radius * Math.cos(angle * i + rotation);
    const y = origin.y + radius * Math.sin(angle * i + rotation);
    points.push({ x, y });
  }
  return points;
}
