  const index: { [key: number]: [JSON, number][] } = {};
  const values: JSON[] = [];
  const counts: number[] = [];

  const add = (value: JSON): number => {
    const key = hash(value);
    const entry = index[key]?.find((x) => eq(x[0], value));

    if (entry != null) {
