function buildCalendar(year?: number): Array<Array<Array<object>>> {
  const currentYear = year ?? new Date().getFullYear();
  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const calendar = [];
  for (let month of months) {
    const monthCalendar = [];
    for (let day of days) {
      const dayCalendar = [];
      for (let i = 1; i <= 31; i++) {
        const date = new Date(currentYear, months.indexOf(month), i);
        const dayOfWeek = date.getDay();
        const dayObject = {
          date,
          meta: {
            otherMonth: dayOfWeek === 0 || dayOfWeek === 6,
          },
        };
        dayCalendar.push(dayObject);
      }
      monthCalendar.push(dayCalendar);
    }
    calendar.push(monthCalendar);
  }
  return calendar;
}
